resource "aws_security_group" "{{sg_name}}" {
  name        = "{{sg_name}}"
  description = "Allow SSH and HTTP"
  vpc_id      = "{{vpc_id}}"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["{{ssh_cidr}}"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "{{instance_name}}" {
  ami                    = "{{ami_id}}"
  instance_type          = "{{instance_type}}"
  key_name               = "{{key_name}}"
  vpc_security_group_ids = [aws_security_group.{{sg_name}}.id]

  tags = {
    Name = "{{instance_name}}"
  }
}
